window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9c0516baf8655ab5"]={"versions": [{"id": "FIG-9c0516baf8655ab5", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) im Kontext des AUTOSAR ECU State Managers (ECUM), eingebettet in einen UML-Diagrammrahmen mit dem Namen <code>sm RUN</code>. Das Diagramm spezifiziert die interne Zerlegung („Breakdown“) des Betriebszustands RUN in seine Unterzustände.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Zustände:</li>\n<li><code>Initial</code> (Pseudozustand: Startzustand / Initial State, gefüllter schwarzer Kreis).</li>\n<li><code>RUN II</code>: Zusammengesetzter bzw. substanzieller Betriebszustand für die Ausführung der Betriebsphase II.</li>\n<li><code>RUN III</code>: Nachfolgender Zustand für die Phase III (POST RUN Vorbereitung).</li>\n<li><code>Final</code> (Endzustand / Final State, gefüllter Kreis mit Kreisumrandung).</li>\n<li>Transitionen und Trigger/Aktionen:</li>\n<li>Transition von <code>Initial</code> nach <code>RUN II</code> (unbedingter Eintritt).</li>\n<li>Transition von <code>RUN II</code> nach <code>RUN III</code> mit Trigger <code>all RUN requests released</code> und Aktion <code>/notify</code>.</li>\n<li>Transition von <code>RUN III</code> nach <code>RUN II</code> mit Trigger <code>RUN requested</code> und Aktion <code>/notify</code>.</li>\n<li>Transition von <code>RUN III</code> nach <code>Final</code> mit Trigger <code>all POST RUN requests released</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Beim Eintritt in den RUN-Zustand erfolgt ausgehend vom Pseudozustand <code>Initial</code> der direkte Übergang in den Unterzustand <code>RUN II</code>.</li>\n<li>Werden alle aktiven RUN-Anforderungen freigegeben (<code>all RUN requests released</code>), wechselt der ECU State Manager von <code>RUN II</code> nach <code>RUN III</code> und sendet dabei eine Benachrichtigung (<code>/notify</code>).</li>\n<li>Geht im Zustand <code>RUN III</code> erneut eine RUN-Anforderung ein (<code>RUN requested</code>), erfolgt eine Rücktransition nach <code>RUN II</code>, ebenfalls begleitet von einer Benachrichtigung (<code>/notify</code>).</li>\n<li>Werden im Zustand <code>RUN III</code> auch alle POST-RUN-Anforderungen freigegeben (<code>all POST RUN requests released</code>), wechselt die Zustandsmaschine in den Endzustand <code>Final</code>, womit die RUN-Phase verlassen wird.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung definiert das geforderte Mindestverhalten für die Verwaltung der RUN-Zustände im ECU State Manager. Implementierer müssen das Vorliegen und den Wegfall von RUN- bzw. POST-RUN-Requests überwachen und bei den entsprechenden Zustandswechseln zwischen RUN II und RUN III die Benachrichtigungen (<code>/notify</code>) an abhängige BSW-Module oder Komponenten auslösen. Der Übergang in <code>Final</code> signalisiert die Bereitschaft zum Verlassen des Gesamtzustands RUN.</p>"}, {"id": "FIG-8c01b293eb083190", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) im Kontext des AUTOSAR ECU State Managers (ECUM) ohne äußeren UML-Rahmen. Das Diagramm spezifiziert die interne Zerlegung („Breakdown“) des Betriebszustands RUN in seine Unterzustände.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Zustände:</li>\n<li><code>Initial</code> (Pseudozustand: Startzustand / Initial State, gefüllter schwarzer Kreis).</li>\n<li><code>RUN II</code>: Zusammengesetzter bzw. substanzieller Betriebszustand für die Ausführung der Betriebsphase II.</li>\n<li><code>RUN III</code>: Nachfolgender Zustand für die Phase III (POST RUN Vorbereitung).</li>\n<li><code>Final</code> (Endzustand / Final State, gefüllter Kreis mit Kreisumrandung).</li>\n<li>Transitionen und Trigger/Aktionen:</li>\n<li>Transition von <code>Initial</code> nach <code>RUN II</code> (unbedingter Eintritt).</li>\n<li>Transition von <code>RUN II</code> nach <code>RUN III</code> mit Trigger <code>all RUN requests released</code> und Aktion <code>/notify</code>.</li>\n<li>Transition von <code>RUN III</code> nach <code>RUN II</code> mit Trigger <code>RUN requested</code> und Aktion <code>/notify</code>.</li>\n<li>Transition von <code>RUN III</code> nach <code>Final</code> mit Trigger <code>all POST RUN requests released</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Beim Eintritt in den RUN-Zustand erfolgt ausgehend vom Pseudozustand <code>Initial</code> der direkte Übergang in den Unterzustand <code>RUN II</code>.</li>\n<li>Werden alle aktiven RUN-Anforderungen freigegeben (<code>all RUN requests released</code>), wechselt der ECU State Manager von <code>RUN II</code> nach <code>RUN III</code> und sendet dabei eine Benachrichtigung (<code>/notify</code>).</li>\n<li>Geht im Zustand <code>RUN III</code> erneut eine RUN-Anforderung ein (<code>RUN requested</code>), erfolgt eine Rücktransition nach <code>RUN II</code>, ebenfalls begleitet von einer Benachrichtigung (<code>/notify</code>).</li>\n<li>Werden im Zustand <code>RUN III</code> auch alle POST-RUN-Anforderungen freigegeben (<code>all POST RUN requests released</code>), wechselt die Zustandsmaschine in den Endzustand <code>Final</code>, womit die RUN-Phase verlassen wird.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung definiert das geforderte Mindestverhalten für die Verwaltung der RUN-Zustände im ECU State Manager. Implementierer müssen das Vorliegen und den Wegfall von RUN- bzw. POST-RUN-Requests überwachen und bei den entsprechenden Zustandswechseln zwischen RUN II und RUN III die Benachrichtigungen (<code>/notify</code>) an abhängige BSW-Module oder Komponenten auslösen. Der Übergang in <code>Final</code> signalisiert die Bereitschaft zum Verlassen des Gesamtzustands RUN.</p>"}, {"id": "FIG-644f7c2e40c57752", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Zustandsdiagramm (State Machine Diagram) im Kontext des AUTOSAR ECU State Managers (ECUM) ohne äußeren UML-Rahmen. Das Diagramm spezifiziert die interne Zerlegung („Breakdown“) des Betriebszustands RUN in seine Unterzustände.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Zustände:</li>\n<li><code>Initial</code> (Pseudozustand: Startzustand / Initial State, gefüllter schwarzer Kreis).</li>\n<li><code>RUN II</code>: Zusammengesetzter bzw. substanzieller Betriebszustand für die Ausführung der Betriebsphase II.</li>\n<li><code>RUN III</code>: Nachfolgender Zustand für die Phase III (POST RUN Vorbereitung).</li>\n<li><code>Final</code> (Endzustand / Final State, gefüllter Kreis mit Kreisumrandung).</li>\n<li>Transitionen und Trigger/Aktionen:</li>\n<li>Transition von <code>Initial</code> nach <code>RUN II</code> (unbedingter Eintritt).</li>\n<li>Transition von <code>RUN II</code> nach <code>RUN III</code> mit Trigger <code>all RUN requests released</code> und Aktion <code>/notify</code>.</li>\n<li>Transition von <code>RUN III</code> nach <code>RUN II</code> mit Trigger <code>RUN requested</code> und Aktion <code>/notify</code>.</li>\n<li>Transition von <code>RUN III</code> nach <code>Final</code> mit Trigger <code>all POST RUN requests released</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Beim Eintritt in den RUN-Zustand erfolgt ausgehend vom Pseudozustand <code>Initial</code> der direkte Übergang in den Unterzustand <code>RUN II</code>.</li>\n<li>Werden alle aktiven RUN-Anforderungen freigegeben (<code>all RUN requests released</code>), wechselt der ECU State Manager von <code>RUN II</code> nach <code>RUN III</code> und sendet dabei eine Benachrichtigung (<code>/notify</code>).</li>\n<li>Geht im Zustand <code>RUN III</code> erneut eine RUN-Anforderung ein (<code>RUN requested</code>), erfolgt eine Rücktransition nach <code>RUN II</code>, ebenfalls begleitet von einer Benachrichtigung (<code>/notify</code>).</li>\n<li>Werden im Zustand <code>RUN III</code> auch alle POST-RUN-Anforderungen freigegeben (<code>all POST RUN requests released</code>), wechselt die Zustandsmaschine in den Endzustand <code>Final</code>, womit die RUN-Phase verlassen wird.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Modellierung definiert das geforderte Mindestverhalten für die Verwaltung der RUN-Zustände im ECU State Manager. Implementierer müssen das Vorliegen und den Wegfall von RUN- bzw. POST-RUN-Requests überwachen und bei den entsprechenden Zustandswechseln zwischen RUN II und RUN III die Benachrichtigungen (<code>/notify</code>) an abhängige BSW-Module oder Komponenten auslösen. Der Übergang in <code>Final</code> signalisiert die Bereitschaft zum Verlassen des Gesamtzustands RUN.</p>"}], "trans": [{"from": "FIG-9c0516baf8655ab5", "to": "FIG-8c01b293eb083190", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>UML-Rahmen: Der äußere Zustandsdiagramm-Rahmen mit dem Kopfbereich <code>sm RUN</code> wurde entfernt.</li>\n<li>Grafik-Export: Weißer Außenabstand und Rahmenkontur entfallen zugunsten eines freigestellten Diagrammbereichs.</li>\n</ul>"}, {"from": "FIG-8c01b293eb083190", "to": "FIG-644f7c2e40c57752", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Zustandssymbole: Die abgerundeten Rechtecke für <code>RUN II</code> und <code>RUN III</code> weisen konkav nach innen geschwungene vertikale Seitenränder auf (Rendering-/Schriftarten- bzw. Vektorersetzungsartefakt).</li>\n<li>Pfeillinie: Die obere Transitionslinie verläuft am oberen Rand durch die beiden Zustandsbegrenzungen hindurch.</li>\n</ul>"}]};
